{
  "@type": "Recipe",
  "name": "Aglio e Olio (Spaghetti with garlic olive oil)",
  "author": {
    "@id": "https://www.recipetineats.com/#/schema/person/1684e6a75e9f91ae2e33ca2de95b47e2"
  },
  "description": "Recipe video above. Aglio e Olio - Garlic Oil Spaghetti - is the classic Italian pantry pasta made with just 3 basic ingredients: pasta, garlic and olive oil. Don&#39;t skimp on the oil, use a good one and get the salt amount right, and you&#39;ll be blown away by how delicious something so simple can be!For quick ways to incorporate vegetables into this, see Note 1. And as for what to do with leftovers - make crispy spaghetti fritters! See Note 4.",
  "datePublished": "2026-09-21T16:00:00+00:00",
  "image": [
    "https://www.recipetineats.com/tachyon/2026/09/Aglio-e-olio-garlic-oil-spaghetti-0.jpg",
    "https://www.recipetineats.com/tachyon/2026/09/Aglio-e-olio-garlic-oil-spaghetti-0.jpg?resize=500%2C500",
    "https://www.recipetineats.com/tachyon/2026/09/Aglio-e-olio-garlic-oil-spaghetti-0.jpg?resize=500%2C375",
    "https://www.recipetineats.com/tachyon/2026/09/Aglio-e-olio-garlic-oil-spaghetti-0.jpg?resize=480%2C270"
  ],
  "recipeYield": [
    "4",
    "4 - 5 people"
  ],
  "prepTime": "PT6M",
  "cookTime": "PT12M",
  "totalTime": "PT18M",
  "recipeIngredient": [
    "500g/ 1 lb  spaghetti ((I use No 5 spaghetti but any long strand pasta will work))",
    "2 tsp cooking salt / kosher salt (, for cooking pasta (halve for table salt, +50% for flakes))",
    "1/2 cup extra virgin olive oil ((the better the oil, the tastier your pasta!))",
    "6  large garlic cloves (, finely sliced)",
    "1/2 tsp red chilli flakes ((red pepper flakes), optional - sub pinch of black pepper for not spicy)",
    "1 tsp cooking salt / kosher salt ((halve for table salt, +50% for flakes))",
    "1/3 cup finely chopped parsley ((Note 2))",
    "1/2 cup reserved pasta cooking water (see Step 2)",
    "Parmesan or parmigiano reggiano (, finely grated, for serving)"
  ],
  "recipeInstructions": [
    {
      "@type": "HowToSection",
      "name": "ABBREVIATED RECIPE:",
      "itemListElement": [
        {
          "@type": "HowToStep",
          "text": "Cook pasta per packet minus 1 minute in salted water, reserve water, drain. Slowly sauté garlic in oil, add chilli flakes, then pasta, 1/2 cup pasta water and salt, toss, finish with parsley. Serve.",
          "name": "Cook pasta per packet minus 1 minute in salted water, reserve water, drain. Slowly sauté garlic in oil, add chilli flakes, then pasta, 1/2 cup pasta water and salt, toss, finish with parsley. Serve.",
          "url": "https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/#wprm-recipe-201489-step-0-0"
        }
      ]
    },
    {
      "@type": "HowToSection",
      "name": "FULL RECIPE:",
      "itemListElement": [
        {
          "@type": "HowToStep",
          "text": "Cook pasta - Bring 4 litres / quarts of water to the boil. Add the 2 teaspoons of salt and the pasta. Cook for the packet direction time, MINUS 1 minute.",
          "name": "Cook pasta - Bring 4 litres / quarts of water to the boil. Add the 2 teaspoons of salt and the pasta. Cook for the packet direction time, MINUS 1 minute.",
          "url": "https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/#wprm-recipe-201489-step-1-0"
        },
        {
          "@type": "HowToStep",
          "text": "Scoop then drain (IMPORTANT!) - Just before draining, scoop out 1 cup of the pasta cooking water. Then drain the pasta.",
          "name": "Scoop then drain (IMPORTANT!) - Just before draining, scoop out 1 cup of the pasta cooking water. Then drain the pasta.",
          "url": "https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/#wprm-recipe-201489-step-1-1"
        },
        {
          "@type": "HowToStep",
          "text": "Garlic oil - 4 minutes before the pasta is ready, heat the oil in a large ~30cm/12&quot; deep pan over medium heat. (Note 3 if you don&#39;t have a pan this size). Add the garlic and sauté gently for 2 - 3 minutes until it is a very light golden brown - don&#39;t rush this step, it&#39;s key to infuse the oil with garlic flavour. Add the chilli flakes and stir for 20 - 30 seconds until the garlic is light golden, do not let the garlic become brown, it will be bitter.",
          "name": "Garlic oil - 4 minutes before the pasta is ready, heat the oil in a large ~30cm/12&quot; deep pan over medium heat. (Note 3 if you don&#39;t have a pan this size). Add the garlic and sauté gently for 2 - 3 minutes until it is a very light golden brown - don&#39;t rush this step, it&#39;s key to infuse the oil with garlic flavour. Add the chilli flakes and stir for 20 - 30 seconds until the garlic is light golden, do not let the garlic become brown, it will be bitter.",
          "url": "https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/#wprm-recipe-201489-step-1-2"
        },
        {
          "@type": "HowToStep",
          "text": "Toss, toss, toss! Add the drained pasta, 1/2 cup pasta cooking water (125 ml) and the salt. Toss over medium high heat until you no longer see water and oil pooled on the base of the pan, it has combined to form a sauce clinging to the pasta (~1 - 1 1/2 minutes). Add parsley, quickly toss through. The pasta should be slippery and slick with sauce. If at any point the pasta gets sticky or gluggy, just add another slosh of pasta water and toss to loosen.",
          "name": "Toss, toss, toss! Add the drained pasta, 1/2 cup pasta cooking water (125 ml) and the salt. Toss over medium high heat until you no longer see water and oil pooled on the base of the pan, it has combined to form a sauce clinging to the pasta (~1 - 1 1/2 minutes). Add parsley, quickly toss through. The pasta should be slippery and slick with sauce. If at any point the pasta gets sticky or gluggy, just add another slosh of pasta water and toss to loosen.",
          "url": "https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/#wprm-recipe-201489-step-1-3"
        },
        {
          "@type": "HowToStep",
          "text": "Serve immediately with a shower of parmesan.",
          "name": "Serve immediately with a shower of parmesan.",
          "url": "https://www.recipetineats.com/aglio-e-olio-garlic-spaghetti/#wprm-recipe-201489-step-1-4"
        }
      ]
    }
  ],
